#include <optional>
#include <print>
#include <vector>

class Queue {
public:
    void push(int x) { items_.push_back(x); }
    std::optional<int> pop() {
        if (head_ == items_.size()) return std::nullopt;
        return items_[head_++];
    }

private:
    std::vector<int> items_;
    std::size_t head_ = 0;
};

int main() {
    Queue q;
    q.push(7);
    q.push(8);
    int a = q.pop().value_or(0);
    int b = q.pop().value_or(0);
    int c = q.pop().value_or(0);
    std::println("{} {} {}", a, b, c);
    return 0;
}
